using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models;

public class PersonTests
{
    [Fact]
    public void FullName_WithLastAndFirst_ReturnsCommaDelimited()
    {
        // Arrange - use Student as concrete implementation of abstract Person
        var student = new Student
        {
            LastName = "Smith",
            FirstMidName = "John"
        };

        // Act
        var result = student.FullName;

        // Assert
        Assert.Equal("Smith, John", result);
    }

    [Fact]
    public void FullName_WithDifferentNames_ReturnsCorrectFormat()
    {
        var instructor = new Instructor
        {
            LastName = "Doe",
            FirstMidName = "Jane"
        };

        Assert.Equal("Doe, Jane", instructor.FullName);
    }
}

public class ErrorViewModelTests
{
    [Fact]
    public void ShowRequestId_WhenRequestIdSet_ReturnsTrue()
    {
        var model = new ErrorViewModel { RequestId = "abc-123" };

        Assert.True(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdNull_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = null };

        Assert.False(model.ShowRequestId);
    }

    [Fact]
    public void ShowRequestId_WhenRequestIdEmpty_ReturnsFalse()
    {
        var model = new ErrorViewModel { RequestId = "" };

        Assert.False(model.ShowRequestId);
    }
}

public class StudentModelTests
{
    [Fact]
    public void Student_InheritsFromPerson_HasExpectedProperties()
    {
        var date = new DateTime(2023, 9, 1);
        var student = new Student
        {
            ID = 1,
            LastName = "Doe",
            FirstMidName = "John",
            EnrollmentDate = date
        };

        Assert.Equal(1, student.ID);
        Assert.Equal("Doe", student.LastName);
        Assert.Equal("John", student.FirstMidName);
        Assert.Equal(date, student.EnrollmentDate);
        Assert.Equal("Doe, John", student.FullName);
    }
}

public class InstructorModelTests
{
    [Fact]
    public void Instructor_InheritsFromPerson_HasExpectedProperties()
    {
        var date = new DateTime(2000, 3, 15);
        var instructor = new Instructor
        {
            ID = 5,
            LastName = "Kim",
            FirstMidName = "Abercrombie",
            HireDate = date
        };

        Assert.Equal(5, instructor.ID);
        Assert.Equal("Kim", instructor.LastName);
        Assert.Equal(date, instructor.HireDate);
        Assert.Equal("Kim, Abercrombie", instructor.FullName);
    }
}

public class CourseModelTests
{
    [Fact]
    public void Course_Properties_SetAndGetCorrectly()
    {
        var course = new Course
        {
            CourseID = 1050,
            Title = "Chemistry",
            Credits = 3,
            DepartmentID = 1
        };

        Assert.Equal(1050, course.CourseID);
        Assert.Equal("Chemistry", course.Title);
        Assert.Equal(3, course.Credits);
        Assert.Equal(1, course.DepartmentID);
    }
}

public class DepartmentModelTests
{
    [Fact]
    public void Department_Properties_SetAndGetCorrectly()
    {
        var date = new DateTime(2007, 9, 1);
        var department = new Department
        {
            DepartmentID = 1,
            Name = "Engineering",
            Budget = 350000m,
            StartDate = date,
            InstructorID = 3
        };

        Assert.Equal(1, department.DepartmentID);
        Assert.Equal("Engineering", department.Name);
        Assert.Equal(350000m, department.Budget);
        Assert.Equal(date, department.StartDate);
        Assert.Equal(3, department.InstructorID);
    }

    [Fact]
    public void Department_InstructorID_AllowsNull()
    {
        var department = new Department { Name = "Test" };

        Assert.Null(department.InstructorID);
    }
}

public class EnrollmentModelTests
{
    [Fact]
    public void Enrollment_Grade_AllowsNull()
    {
        var enrollment = new Enrollment
        {
            EnrollmentID = 1,
            CourseID = 100,
            StudentID = 1
        };

        Assert.Null(enrollment.Grade);
    }

    [Theory]
    [InlineData(Grade.A)]
    [InlineData(Grade.B)]
