namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    private static IQueryable<int> CreateSource(int count)
    {
        return Enumerable.Range(1, count).AsQueryable();
    }

    [Fact]
    public void Create_FirstPage_ContainsCorrectItems()
    {
        // Arrange
        var source = CreateSource(25);

        // Act
        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_SecondPage_ContainsCorrectItems()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.Equal(10, result.Count);
        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
        Assert.Equal(2, result.PageIndex);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void HasPreviousPage_OnFirstPage_ReturnsFalse()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_OnSecondPage_ReturnsTrue()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 2, pageSize: 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_OnFirstPageWithMorePages_ReturnsTrue()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_OnLastPage_ReturnsFalse()
    {
        var source = CreateSource(25);

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void TotalPages_CalculatedCorrectly_WhenEvenlyDivisible()
    {
        var source = CreateSource(20);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(2, result.TotalPages);
    }

    [Fact]
    public void TotalPages_RoundsUp_WhenNotEvenlyDivisible()
    {
        var source = CreateSource(21);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyListWithZeroPages()
    {
        var source = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
        Assert.Equal(1, result.PageIndex);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_SinglePage_HasNoPreviousOrNextPage()
    {
        var source = CreateSource(5);

        var result = PaginatedList<int>.Create(source, pageIndex: 1, pageSize: 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<string> { "a", "b", "c" };

        var result = new PaginatedList<string>(items, count: 30, pageIndex: 2, pageSize: 10);

        Assert.Equal(3, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.Contains("a", result);
        Assert.Contains("b", result);
        Assert.Contains("c", result);
    }

    [Fact]
    public void HasPreviousPage_MiddlePage_ReturnsTrue()
    {
        var source = CreateSource(50);

        var result = PaginatedList<int>.Create(source, pageIndex: 3, pageSize: 10);

        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }
}

