using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewFeatures;

namespace ContosoUniversity.Tests.Controllers;

public class NotificationsControllerTests : IDisposable
{
    private readonly SchoolContext _context;
    private readonly NotificationsController _sut;

    public NotificationsControllerTests()
    {
        _context = TestDbContextFactory.Create();
        _sut = new NotificationsController(_context);
        _sut.TempData = new TempDataDictionary(new DefaultHttpContext(), new SessionStateTempDataProvider(new SessionStateTempDataSerializer()));
        // Drain any leftover notifications from static queue
        var ns = new NotificationService();
        while (ns.ReceiveNotification() != null) { }
        ns.Dispose();
    }

    public void Dispose()
    {
        // Drain to avoid cross-test contamination
        var ns = new NotificationService();
        while (ns.ReceiveNotification() != null) { }
        ns.Dispose();
        _sut.Dispose();
        _context.Dispose();
    }

    [Fact]
    public void GetNotifications_NoNotifications_ReturnsEmptyList()
    {
        var result = _sut.GetNotifications();

        Assert.NotNull(result);
        var json = result.Value;
        Assert.NotNull(json);
        // Access via dynamic
        var successProp = json.GetType().GetProperty("success");
        var countProp = json.GetType().GetProperty("count");
        Assert.True((bool)successProp!.GetValue(json)!);
        Assert.Equal(0, (int)countProp!.GetValue(json)!);
    }

    [Fact]
    public void GetNotifications_WithNotifications_ReturnsNotifications()
    {
        // Arrange - send some notifications via the service
        var ns = new NotificationService();
        ns.SendNotification("Student", "1", "John", EntityOperation.CREATE, "Admin");
        ns.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");
        ns.Dispose();

        // Act
        var result = _sut.GetNotifications();

        // Assert
        var json = result.Value;
        Assert.NotNull(json);
        var countProp = json.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(json)!;
        Assert.Equal(2, count);
    }

    [Fact]
    public void GetNotifications_MoreThan10_LimitsTo10()
    {
        var ns = new NotificationService();
        for (int i = 0; i < 15; i++)
        {
            ns.SendNotification("Type", i.ToString(), EntityOperation.CREATE);
        }
        ns.Dispose();

        var result = _sut.GetNotifications();

        var json = result.Value;
        Assert.NotNull(json);
        var countProp = json.GetType().GetProperty("count");
        var count = (int)countProp!.GetValue(json)!;
        Assert.Equal(10, count);
    }

    [Fact]
    public void MarkAsRead_ReturnsSuccessJson()
    {
        var result = _sut.MarkAsRead(1);

        Assert.NotNull(result);
        var json = result.Value;
        Assert.NotNull(json);
        var successProp = json.GetType().GetProperty("success");
        Assert.True((bool)successProp!.GetValue(json)!);
    }

    [Fact]
    public void Index_ReturnsViewResult()
    {
        var result = _sut.Index();

        Assert.IsType<ViewResult>(result);
    }
}

