 using ContosoUniversity.Controllers;
 using ContosoUniversity.Data;
 using ContosoUniversity.Models;
 using ContosoUniversity.Tests.Helpers;
 using Microsoft.AspNetCore.Http;
 using Microsoft.AspNetCore.Mvc;
 using Microsoft.AspNetCore.Mvc.ViewFeatures;
 using Moq;

 namespace ContosoUniversity.Tests.Controllers;

 public class StudentsControllerTests : IDisposable
 {
     private readonly SchoolContext _context;
     private readonly StudentsController _sut;

     public StudentsControllerTests()
     {
         _context = TestDbContextFactory.Create();
         _sut = new StudentsController(_context);
         _sut.TempData = new TempDataDictionary(new DefaultHttpContext(), Mock.Of<ITempDataProvider>());
     }

     public void Dispose()
     {
         _sut.Dispose();
         _context.Dispose();
     }

     private Student CreateTestStudent(string firstName = "John", string lastName = "Doe", DateTime? enrollmentDate = null)
     {
         var student = new Student
         {
             FirstMidName = firstName,
             LastName = lastName,
             EnrollmentDate = enrollmentDate ?? new DateTime(2023, 9, 1)
         };
         _context.Students.Add(student);
         _context.SaveChanges();
         return student;
     }

     // === Index ===

     [Fact]
     public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
     {
         CreateTestStudent("Alice", "Zeta");
         CreateTestStudent("Bob", "Alpha");

         var result = _sut.Index(null, null, null, null) as ViewResult;

         Assert.NotNull(result);
         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result.Model);
         Assert.Equal(2, model.Count);
         Assert.Equal("Alpha", model[0].LastName);
         Assert.Equal("Zeta", model[1].LastName);
     }

     [Fact]
     public void Index_NameDescSort_ReturnsDescendingOrder()
     {
         CreateTestStudent("Alice", "Alpha");
         CreateTestStudent("Bob", "Zeta");

         var result = _sut.Index("name_desc", null, null, null) as ViewResult;

         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
         Assert.Equal("Zeta", model[0].LastName);
         Assert.Equal("Alpha", model[1].LastName);
     }

     [Fact]
     public void Index_DateSort_ReturnsOrderByEnrollmentDate()
     {
         CreateTestStudent("Alice", "Alpha", new DateTime(2023, 1, 1));
         CreateTestStudent("Bob", "Beta", new DateTime(2020, 1, 1));

         var result = _sut.Index("Date", null, null, null) as ViewResult;

         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
         Assert.Equal("Beta", model[0].LastName); // 2020 before 2023
     }

     [Fact]
     public void Index_DateDescSort_ReturnsDescendingByDate()
     {
         CreateTestStudent("Alice", "Alpha", new DateTime(2020, 1, 1));
         CreateTestStudent("Bob", "Beta", new DateTime(2023, 1, 1));

         var result = _sut.Index("date_desc", null, null, null) as ViewResult;

         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
         Assert.Equal("Beta", model[0].LastName); // 2023 first
     }

     [Fact]
     public void Index_SearchString_FiltersStudentsByLastName()
     {
         CreateTestStudent("Alice", "Smith");
         CreateTestStudent("Bob", "Johnson");

         var result = _sut.Index(null, null, "Smith", null) as ViewResult;

         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
         Assert.Single(model);
         Assert.Equal("Smith", model[0].LastName);
     }

     [Fact]
     public void Index_SearchString_FiltersStudentsByFirstName()
     {
         CreateTestStudent("Alice", "Smith");
         CreateTestStudent("Bob", "Johnson");

         var result = _sut.Index(null, null, "Alice", null) as ViewResult;

         var model = Assert.IsAssignableFrom<PaginatedList<Student>>(result!.Model);
         Assert.Single(model);
         Assert.Equal("Alice", model[0].FirstMidName);
     }

     [Fact]
     public void Index_NewSearchString_ResetsPageTo1()
     {
         var result = _sut.Index(null, null, "test", 5) as ViewResult;

         // When searchString is provided (not null), page resets to 1
         Assert.NotNull(result);
     }

     [Fact]
     public void Index_SetsViewBagSortParams()
     {
         _sut.Index(null, null, null, null);

         Assert.Equal("name_desc", _sut.ViewBag.NameSortParm);
         Assert.Equal("Date", _sut.ViewBag.DateSortParm);
     }

     [Fact]
     public void Index_WithSortOrder_SetsCorrectSortParms()
     {
         _sut.Index("Date", null, null, null);

         Assert.Equal("", _sut.ViewBag.NameSortParm);
         Assert.Equal("date_desc", _sut.ViewBag.DateSortParm);
     }

     // === Details ===

     [Fact]
     public void Details_NullId_ReturnsBadRequest()
     {
         var result = _sut.Details(null);

         var statusResult = Assert.IsType<StatusCodeResult>(result);
         Assert.Equal(400, statusResult.StatusCode);
     }

     [Fact]
     public void Details_ValidId_ReturnsViewWithStudent()
     {
         var student = CreateTestStudent();

         var result = _sut.Details(student.ID) as ViewResult;

         Assert.NotNull(result);
         var model = Assert.IsType<Student>(result.Model);
         Assert.Equal(student.ID, model.ID);
         Assert.Equal("John", model.FirstMidName);
     }

     // === Create GET ===

     [Fact]
     public void Create_Get_ReturnsViewWithStudentAndDefaultDate()
     {
         var result = _sut.Create() as ViewResult;

         Assert.NotNull(result);
         var model = Assert.IsType<Student>(result.Model);
         Assert.Equal(DateTime.Today, model.EnrollmentDate);
     }

     // === Create POST ===

     [Fact]
     public void Create_Post_ValidStudent_RedirectsToIndex()
     {
         var student = new Student
         {
             FirstMidName = "New",
             LastName = "Student",
             EnrollmentDate = new DateTime(2023, 9, 1)
         };

         var result = _sut.Create(student);

         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
     }

     [Fact]
     public void Create_Post_ValidStudent_SavesInDatabase()
     {
         var student = new Student
         {
             FirstMidName = "New",
             LastName = "Student",
             EnrollmentDate = new DateTime(2023, 9, 1)
         };

         _sut.Create(student);

         var saved = _context.Students.Single();
         Assert.Equal("New", saved.FirstMidName);
         Assert.Equal("Student", saved.LastName);
         Assert.Equal(new DateTime(2023, 9, 1), saved.EnrollmentDate);
     }

     [Fact]
     public void Create_Post_DefaultDate_AddsModelError()
     {
         var student = new Student
         {
             FirstMidName = "New",
             LastName = "Student",
             EnrollmentDate = DateTime.MinValue
         };

         var result = _sut.Create(student);

         var viewResult = Assert.IsType<ViewResult>(result);
         Assert.False(_sut.ModelState.IsValid);
         Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
     }

     [Fact]
     public void Create_Post_InvalidModelState_ReturnsViewWithStudent()
     {
         _sut.ModelState.AddModelError("LastName", "Required");
         var student = new Student
         {
             FirstMidName = "Test",
             EnrollmentDate = new DateTime(2023, 1, 1)
         };

         var result = _sut.Create(student);

         var viewResult = Assert.IsType<ViewResult>(result);
         Assert.Same(student, viewResult.Model);
     }

     [Fact]
     public void Create_Post_DateBeforeSqlRange_AddsModelError()
     {
         var student = new Student
         {
             FirstMidName = "Test",
             LastName = "Test",
             EnrollmentDate = new DateTime(1700, 1, 1)
         };

         _sut.Create(student);

         Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
     }

     // === Edit GET ===

     [Fact]
     public void Edit_Get_NullId_ReturnsBadRequest()
