         var result = _sut.Edit((int?)null);

         var statusResult = Assert.IsType<StatusCodeResult>(result);
         Assert.Equal(400, statusResult.StatusCode);
     }

     [Fact]
     public void Edit_Get_InvalidId_ReturnsNotFound()
     {
         var result = _sut.Edit(999);

         Assert.IsType<NotFoundResult>(result);
     }

     [Fact]
     public void Edit_Get_ValidId_ReturnsViewWithStudent()
     {
         var student = CreateTestStudent();

         var result = _sut.Edit(student.ID) as ViewResult;

         Assert.NotNull(result);
         var model = Assert.IsType<Student>(result.Model);
         Assert.Equal(student.ID, model.ID);
     }

     // === Edit POST ===

     [Fact]
     public void Edit_Post_ValidStudent_RedirectsToIndex()
     {
         var student = CreateTestStudent();
         // Detach the tracked entity so we can attach the edited one
         _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

         var editedStudent = new Student
         {
             ID = student.ID,
             FirstMidName = "Edited",
             LastName = "Name",
             EnrollmentDate = new DateTime(2023, 9, 1)
         };

         var result = _sut.Edit(editedStudent);

         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
     }

     [Fact]
     public void Edit_Post_DefaultDate_AddsModelError()
     {
         var student = new Student
         {
             ID = 1,
             FirstMidName = "Test",
             LastName = "Test",
             EnrollmentDate = default
         };

         _sut.Edit(student);

         Assert.True(_sut.ModelState.ContainsKey("EnrollmentDate"));
     }

     [Fact]
     public void Edit_Post_InvalidModelState_ReturnsView()
     {
         _sut.ModelState.AddModelError("LastName", "Required");
         var student = new Student
         {
             ID = 1,
             FirstMidName = "Test",
             EnrollmentDate = new DateTime(2023, 1, 1)
         };

         var result = _sut.Edit(student);

         Assert.IsType<ViewResult>(result);
     }

     // === Delete GET ===

     [Fact]
     public void Delete_Get_NullId_ReturnsBadRequest()
     {
         var result = _sut.Delete(null);

         var statusResult = Assert.IsType<StatusCodeResult>(result);
         Assert.Equal(400, statusResult.StatusCode);
     }

     [Fact]
     public void Delete_Get_InvalidId_ReturnsNotFound()
     {
         var result = _sut.Delete(999);

         Assert.IsType<NotFoundResult>(result);
     }

     [Fact]
     public void Delete_Get_ValidId_ReturnsViewWithStudent()
     {
         var student = CreateTestStudent();

         var result = _sut.Delete(student.ID) as ViewResult;

         Assert.NotNull(result);
         var model = Assert.IsType<Student>(result.Model);
         Assert.Equal(student.ID, model.ID);
     }

     // === DeleteConfirmed ===

     [Fact]
     public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
     {
         var student = CreateTestStudent();

         var result = _sut.DeleteConfirmed(student.ID);

         var redirect = Assert.IsType<RedirectToActionResult>(result);
         Assert.Equal("Index", redirect.ActionName);
         Assert.Empty(_context.Students);
     }
 }

