public void Edit_Post_ValidStudent_RedirectsToIndex()
{
    var student = CreateTestStudent();
    // Detach the tracked entity so we can attach the edited one
    _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

    var editedStudent = new Student
    {
        ID = student.ID,
        FirstMidName = "Edited",
        LastName = "Name",
        EnrollmentDate = new DateTime(2023, 9, 1)
    };

    var result = _sut.Edit(editedStudent);

    var redirect = Assert.IsType<RedirectToActionResult>(result);
    Assert.Equal("Index", redirect.ActionName);

    // Verify DB was actually updated
    _context.Entry(editedStudent).State = Microsoft.EntityFrameworkCore.EntityState.Detached;
    var updated = _context.Students.Single(s => s.ID == student.ID);
    Assert.Equal("Edited", updated.FirstMidName);
    Assert.Equal("Name", updated.LastName);
    Assert.Equal(new DateTime(2023, 9, 1), updated.EnrollmentDate);
}

